import numpy as np


def symmetric_int8_quantize(x: np.ndarray, scale: float) -> np.ndarray:
    q = np.round(x / scale)
    q = np.clip(q, -127, 127)
    return q.astype(np.int8)


def symmetric_int8_dequantize(q: np.ndarray, scale: float) -> np.ndarray:
    return q.astype(np.float32) * scale

import numpy as np


def enl(patch: np.ndarray) -> float:
    mean = float(np.mean(patch))
    std = float(np.std(patch))
    if std == 0.0:
        return float("inf")
    return (mean / std) ** 2


def epi(reference: np.ndarray, output: np.ndarray) -> float:
    g_ref = np.diff(reference, axis=1).ravel()
    g_out = np.diff(output, axis=1).ravel()
    if np.std(g_ref) == 0.0 or np.std(g_out) == 0.0:
        return 0.0
    return float(np.corrcoef(g_ref, g_out)[0, 1])
